local bbase=np.array({{{0,1,2},{3,4,5}}},"uint8")
local base=abase
local a=np.flip(base,-1)
base=bbase
local b=np.flip(base,-1)
local ok,result=pcall(function()return np.linalg.cross(a,b,-1)end)
assert(ok==true,"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: acceptance"..": "..tostring(result))
active_dtype="uint8"
eq(result:tolist(),{{{0,0,0},{0,0,0}}},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: result: values",0)
eq(result.shape,{1,2,3},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: result: shape")
eq(result.strides,{6,3,1},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: result: strides")
eq(result.dtype,"uint8","cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: result: dtype")
active_dtype=nil
eq(np.shares_memory(result,a),false,"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: shares a")
eq(np.shares_memory(result,b),false,"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: shares b")
eq(a:tolist(),{{{2,1,0},{5,4,3}}},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input a: values",0)
eq(a.shape,{1,2,3},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input a: shape")
eq(a.strides,{6,3,-1},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input a: strides")
eq(a.dtype,"uint8","cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input a: dtype")
eq(b:tolist(),{{{2,1,0},{5,4,3}}},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input b: values",0)
eq(b.shape,{1,2,3},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input b: shape")
eq(b.strides,{6,3,-1},"cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input b: strides")
eq(b.dtype,"uint8","cross/uint8(1, 2, 3)/uint8(1, 2, 3)/(-1, -1, -1)/reverse_last/linalgTrue/rawFalse/generalFalse: input b: dtype")
cases=cases+1
end
