eq(a.dtype,"float64","cross/float64()/float64()/(-1, -1, -1)/transpose/linalgTrue/rawFalse/generalFalse: input a: dtype")
eq(np.logical_and(np.signbit(a),np.equal(a,0)):tolist(),false,"cross/float64()/float64()/(-1, -1, -1)/transpose/linalgTrue/rawFalse/generalFalse: input a: signed zero")
