eq(b.shape,{},"cross/float64()/float64()/(-1, -1, -1)/transpose/linalgTrue/rawFalse/generalFalse: input b: shape")
eq(b.strides,{},"cross/float64()/float64()/(-1, -1, -1)/transpose/linalgTrue/rawFalse/generalFalse: input b: strides")
