eq(np.logical_and(np.signbit(b),np.equal(b,0)):tolist(),false,"cross/float64()/float64()/(-1, -1, -1)/transpose/linalgTrue/rawFalse/generalFalse: input b: signed zero")
cases=cases+1
end
